package androidx.fragment.app;public class Fragment{public android.view.View root;public boolean removing,missingPicker;public android.content.Intent lastIntent;public int lastRequest;public android.view.View getView(){return root;}public android.content.Context getContext(){return root==null?null:root.getContext();}public android.content.Context requireContext(){return getContext();}public boolean isAdded(){return root!=null;}public boolean isRemoving(){return removing;}public FragmentManager getParentFragmentManager(){return new FragmentManager();}public void startActivityForResult(android.content.Intent i,int r){if(missingPicker)throw new android.content.ActivityNotFoundException();lastIntent=i;lastRequest=r;}}